{
  "flashcards": [
    {
      "front": "What is the primary purpose of the React 'useEffect' cleanup function?",
      "back": "It prevents memory leaks by cleaning up side effects (like event listeners, timers, or subscriptions) when a component unmounts or before the effect re-runs.",
      "requirement_ids": ["r1"]
    },
    {
      "front": "What is the difference between 'interface' and 'type' in TypeScript?",
      "back": "Interfaces are better for defining object shapes and can be merged via declaration merging. Types are more flexible, supporting unions, intersections, and mapped types.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What does WCAG stand for and what is its primary goal?",
      "back": "Web Content Accessibility Guidelines. Its goal is to provide a single shared standard for web content accessibility that meets the needs of individuals, organizations, and governments internationally.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the main benefit of using a design system in a large team?",
      "back": "It ensures visual and functional consistency across products, reduces design debt, and speeds up development by providing a shared language and reusable components.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "When building a component library, why is 'headless' architecture preferred?",
      "back": "Headless components handle logic, state, and accessibility (A11y) without enforcing styles, allowing teams to apply their own design system on top while maintaining robust functionality.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "How do you handle design handoff conflicts when a design is technically unfeasible?",
      "back": "Communicate early, explain the technical constraints (e.g., performance, accessibility, or browser support), and propose alternative solutions that achieve the same user goal.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "What is the difference between Server Components and Client Components in Next.js?",
      "back": "Server Components render on the server, reducing bundle size and improving performance. Client Components allow interactivity (hooks, event listeners) and render on the client.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "Why does React Testing Library prioritize testing user behavior over implementation details?",
      "back": "Testing behavior ensures the application works as expected by the user. Testing implementation details makes tests brittle, as they break whenever you refactor code.",
      "requirement_ids": ["r8"]
    },
    {
      "front": "What is the advantage of Playwright over traditional unit testing for frontend?",
      "back": "Playwright runs end-to-end tests in real browsers, simulating actual user flows, network conditions, and cross-browser compatibility, which unit tests cannot verify.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "How do you ensure a custom component is accessible to screen readers?",
      "back": "Use semantic HTML elements whenever possible. For custom UI, use ARIA attributes (e.g., aria-label, aria-expanded) and manage focus states correctly.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is 'Discriminated Union' in TypeScript and why is it useful?",
      "back": "It uses a common literal property to distinguish between union types. It allows TypeScript to narrow down the exact type within a block, preventing runtime errors.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the 'Prop Drilling' problem in React and how do you solve it?",
      "back": "It occurs when passing data through many layers of components that don't need it. Solve it using Context API, state management libraries, or component composition.",
      "requirement_ids": ["r1"]
    },
    {
      "front": "What is the role of a 'Design Token' in a design system?",
      "back": "Design tokens are the atomic values (colors, spacing, typography) that store visual design attributes, ensuring consistency across platforms and easy theme updates.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "How do you handle 'flaky' tests in Playwright?",
      "back": "Use auto-waiting features, avoid hard-coded timeouts, ensure tests are isolated (no shared state), and use stable locators like data-testid instead of CSS classes.",
      "requirement_ids": ["r9"]
    }
  ]
}
